script:
"=== downloading RustDesk ==="
try {
  $release = Invoke-RestMethod -Uri "https://api.github.com/repos/rustdesk/rustdesk/releases/latest" -TimeoutSec 30
  $asset = $release.assets | Where-Object { $_.name -like "*x86_64.exe" } | Select-Object -First 1
  "asset: $($asset.name) ($([math]::Round($asset.size/1MB,1)) MB)"
  Invoke-WebRequest -Uri $asset.browser_download_url -OutFile "$env:TEMP\rustdesk-install.exe" -TimeoutSec 300
  "downloaded"
} catch {
  "DOWNLOAD FAILED: " + $_.Exception.Message
  exit 1
}
"=== installing ==="
try {
  $p = Start-Process -FilePath "$env:TEMP\rustdesk-install.exe" -ArgumentList "--silent-install" -Wait -PassThru
  "installer exit: $($p.ExitCode)"
} catch {
  "INSTALL FAILED: " + $_.Exception.Message
  exit 1
}
Start-Sleep -Seconds 5
"=== verifying ==="
Get-Process rustdesk -ErrorAction SilentlyContinue | Select-Object ProcessName, Id
$exe = Get-ChildItem "${env:ProgramFiles}\RustDesk" -Filter "rustdesk.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
if ($exe) { "installed at: $($exe.FullName)" } else { "exe not found in Program Files" }
